import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';

/**
 * Create a draft invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }} params
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: 'draft', lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }> } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) return customerResult;

  const dateResult = validateDate(issueDate);
  if (!dateResult.ok) return dateResult;

  if (!lines || !Array.isArray(lines) || lines.length === 0) {
    return fail('NO_LINES');
  }

  const tierDiscount = TIER_DISCOUNTS[customerResult.value.tier];

  const enrichedLines = [];
  for (const line of lines) {
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    const discountValidation = validateDiscount(line.discountPercent);
    if (!discountValidation.ok) return discountValidation;

    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    const discountPercent = line.discountPercent !== undefined ? line.discountPercent : tierDiscount;

    enrichedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId,
    issueDate,
    status: 'draft',
    lines: enrichedLines,
  });
}

function validateDate(dateStr) {
  const dateRegex = /^(\d{4})-(\d{2})-(\d{2})$/;
  const match = dateRegex.exec(String(dateStr || ''));

  if (!match) return fail('DATE_INVALID');

  const year = parseInt(match[1], 10);
  const month = parseInt(match[2], 10);
  const day = parseInt(match[3], 10);

  if (!isValidDate(year, month, day)) {
    return fail('DATE_INVALID');
  }

  return ok(true);
}

function isValidDate(year, month, day) {
  if (month < 1 || month > 12) return false;
  if (day < 1) return false;

  const daysInMonth = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

  if (month === 2 && ((year % 4 === 0 && year % 100 !== 0) || year % 400 === 0)) {
    return day <= 29;
  }

  return day <= daysInMonth[month - 1];
}

/**
 * Calculate the total for a single line (qty × unitPrice).
 * @param {{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }} line
 * @returns {number} Total in cents
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the discount for a single line.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number} Discount in cents
 */
export function lineDiscount(line) {
  if (!line.discountPercent || line.discountPercent === 0) {
    return 0;
  }
  const total = lineTotal(line);
  return roundCents(total * line.discountPercent / 100);
}

/**
 * Calculate subtotal, discount, and total for an invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent?: number }> }} invoice
 * @returns {{ subtotal: number, discount: number, total: number }} Amounts in cents
 */
export function invoiceTotals(invoice) {
  let subtotal = 0;
  let discount = 0;

  for (const line of invoice.lines) {
    subtotal += lineTotal(line);
    discount += lineDiscount(line);
  }

  const total = Math.max(0, subtotal - discount);

  return { subtotal: Math.max(0, subtotal), discount: Math.max(0, discount), total };
}

/**
 * Add a line item to a draft invoice. If the SKU already exists, increase its qty.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} params
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: 'draft', lines: Array } } | { ok: false, error: string }}
 */
