test('invoiceTotals calculates subtotal and total for single line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });

  const totals = invoiceTotals(r.value);
