test('invoiceTotals calculates subtotal and total for multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 3 },
      { sku: 'HOST-MONTH', qty: 1 },
    ],
  });

  const totals = invoiceTotals(r.value);
  const subtotal = 2 * 8500 + 3 * 9500 + 1 * 1500;
